fn powerOfThree(n: int) -> bool {
    var i = 0
    var power = 1
    while power <= n {
        if power == n {
            return true
        }
        i += 1
        power *= 3
    }
    return false
}

fn endRun(n: int, k: int) -> int {
    var count = 0
    var current = n
    while current % k == 0 {
        current /= k
        count += 1
    }
    return count
}
